 16	func (s *Server) createPayment(w http.ResponseWriter, r *http.Request) {
 17		var req createPaymentRequest
 18		if err := decodeJSON(r, &req); err != nil {
 19			writeError(w, err)
 20			return
 21		}
 22		amount, err := money.Parse(req.Amount, req.Currency)
 23		if err != nil {
 24			writeError(w, fmt.Errorf("amount: %w", err))
 25			return
 26		}
 27		in := payment.CreateInput{MerchantID: req.MerchantID, Amount: amount}
 28		s.idempotent(w, r, createFingerprint(in), func() (int, any) {
 29			p, err := s.svc.Create(r.Context(), in)
 30			if err != nil {
 31				return errorResponse(err)
 32			}
 33			return http.StatusCreated, toPaymentResponse(p)
 34		})
 35	}
